# delta_mesh_cell_cxs + delta_mesh_fabric_<X>x<Y>xZ>_cxs -- the
# delta mesh router cell wrapped per-port with native CXS planes
# (delta_mesh_plane_{axis,cxs}_{tx,rx}); the core-facing side of
# every plane is the identical internal AXI-Stream record, the
# outer side is native AMBA 5 CXS (IHI 0079 Issue D: credit
# return, TID->CXSSRCID, TDEST->CXSTGTID, TSTRB in CXSUSER,
# CXSMAXPKTPERFLIT=2, 16-byte start alignment). Select with
# --ifc cxs (axis remains the default and ships delta_mesh.f).
#
# Generated by projects/components/fabric-gen-ip/delta/bin/delta_generator.py
#   --topology mesh --cells-x 4 --cells-y 4
#   --cells-z 1 --user-width 64 --ifc cxs
#   (checked-in artifact from the default 4x4x1 config).
#
# Sources: the house CXS link endpoints first (cxs_master/slave;
# their nested -f lists carry cxs_pkg, the gaxi FIFO/skid deps,
# and the cxs helpers), then the house arbiter the cell core
# instantiates, then the four planes, the AXIS core cell (the CXS
# wrapper instantiates it unchanged), the CXS wrapper, and the
# CXS fabric top. Root path token is $REPO_ROOT.

+incdir+$REPO_ROOT/rtl/amba/includes

-f $REPO_ROOT/rtl/amba/filelists/cxs_master.f
-f $REPO_ROOT/rtl/amba/filelists/cxs_slave.f
-f $REPO_ROOT/projects/components/utility-ip/converters/rtl/filelists/axis_to_cxs.f
-f $REPO_ROOT/projects/components/utility-ip/converters/rtl/filelists/cxs_to_axis.f

$REPO_ROOT/rtl/amba/includes/fifo_defs.svh

$REPO_ROOT/rtl/common/arbiter_matrix.sv

$REPO_ROOT/projects/components/fabric-gen-ip/delta/rtl/delta_mesh_plane_axis_tx.sv
$REPO_ROOT/projects/components/fabric-gen-ip/delta/rtl/delta_mesh_plane_axis_rx.sv
$REPO_ROOT/projects/components/fabric-gen-ip/delta/rtl/delta_mesh_plane_cxs_tx.sv
$REPO_ROOT/projects/components/fabric-gen-ip/delta/rtl/delta_mesh_plane_cxs_rx.sv

$REPO_ROOT/projects/components/fabric-gen-ip/delta/rtl/delta_mesh_cell.sv
$REPO_ROOT/projects/components/fabric-gen-ip/delta/rtl/delta_mesh_cell_cxs.sv

$REPO_ROOT/projects/components/fabric-gen-ip/delta/rtl/delta_mesh_fabric_4x4x1_cxs.sv
